37: 
38: // The form asks for the workshop's date and times on the Dublin clock,
39: // whatever the organiser's own zone, so its defaults are Dublin times too.
40: const DEFAULT_START_TIME = "10:00";
41: const DEFAULT_END_TIME = "12:00";
42: 
43: interface Props {
44: 	mode: "create" | "edit";
45: 	initialData?: Partial<{
46: 		title: string;
47: 		description: string;
48: 		location: string;
49: 		workshop_date: Date;
50: 		workshop_end_date: Date;
51: 		max_capacity: number;
52: 		price_member: number;
53: 		price_non_member: number;
54: 		is_public: boolean;
55: 		refund_deadline_days: number | null;
56: 		announce_discord: boolean;
57: 		announce_email: boolean;
58: 	}>;
59: 	onSuccess?: (result: { success: string; workshopId?: string }) => void;
60: 	priceEditingDisabled?: boolean;
61: 	workshopStatus?: string | null;
62: 	workshopEditable?: boolean;
63: }
64: 
65: let {
66: 	mode,
67: 	initialData,
68: 	onSuccess,
69: 	priceEditingDisabled = false,
70: 	workshopStatus,
71: 	workshopEditable,
72: }: Props = $props();
73: 
74: // Select the appropriate form based on mode
75: const remoteForm = $derived(
76: 	mode === "create" ? createWorkshop : updateWorkshop,
77: );
78: const baseInitialFormValue = $derived.by(() => ({
79: 	title: initialData?.title ?? "",
80: 	description: initialData?.description ?? "",
81: 	location: initialData?.location ?? "",
82: 	workshop_date: initialData?.workshop_date
83: 		? initialData.workshop_date.toISOString()
84: 		: "",
85: 	workshop_end_date: initialData?.workshop_end_date
86: 		? initialData.workshop_end_date.toISOString()
87: 		: "",
88: 	max_capacity: initialData?.max_capacity ?? 1,
89: 	price_member: initialData?.price_member ?? 0,
90: 	price_non_member: initialData?.price_non_member ?? 0,
91: 	is_public: initialData?.is_public ?? false,
92: 	refund_deadline_days: initialData?.refund_deadline_days ?? undefined,
93: }));
94: const createInitialFormValue = $derived({
95: 	...baseInitialFormValue,
96: 	announce_discord: initialData?.announce_discord ?? false,
97: 	announce_email: initialData?.announce_email ?? false,
98: });
99: const updateInitialFormValue = $derived({ ...baseInitialFormValue });
100: 
101: // Current callers pass a static mode, so initialize only the selected
102: // module-scoped remote form and avoid clobbering another mounted form instance.
103: if (untrack(() => mode) === "create") {
104: 	initForm(createWorkshop, () => createInitialFormValue);
105: } else {
106: 	initForm(updateWorkshop, () => updateInitialFormValue);
107: }
108: 
109: // Derived values for reading form state
110: const workshopDate = $derived(remoteForm.fields.workshop_date.value());
111: const workshopEndDate = $derived(remoteForm.fields.workshop_end_date.value());
112: const isPublic = $derived(Boolean(remoteForm.fields.is_public.value()));
113: const title = $derived(String(remoteForm.fields.title.value() ?? ""));
114: const location = $derived(String(remoteForm.fields.location.value() ?? ""));
