127: const announceDiscord = $derived(
128: 	mode === "create" && Boolean(createWorkshop.fields.announce_discord.value()),
129: );
130: const announceEmail = $derived(
131: 	mode === "create" && Boolean(createWorkshop.fields.announce_email.value()),
132: );
