134: /**
135:  * A submitted instant as the Dublin civil date and `HH:MM` the form edits, or
136:  * `undefined` when the field is empty or unreadable.
137:  */
138: function onDublinClock(iso: string | undefined) {
139: 	if (!iso || Number.isNaN(Date.parse(iso))) {
140: 		return undefined;
141: 	}
142: 	const [date, time] = dublinWallClock(iso).split(" ");
143: 	return { date, time };
144: }
145: 
146: const start = $derived(onDublinClock(workshopDate));
147: const end = $derived(onDublinClock(workshopEndDate));
148: 
149: const scheduleDate = $derived(
150: 	start ? formatCivilDate(start.date) : "Date not set",
151: );
152: 
153: const scheduleTime = $derived(
154: 	start && end ? `${start.time}–${end.time}` : "Time not set",
155: );
156: 
157: const setupChecklist = $derived([
158: 	{
159: 		label: "Workshop details",
160: 		complete: Boolean(title.trim() && location.trim()),
161: 	},
162: 	{
163: 		label: "Date and time",
164: 		complete: Boolean(workshopDate && workshopEndDate),
165: 	},
166: 	{
167: 		label: "Registration setup",
168: 		complete: maxCapacity >= 1 && memberPrice >= 0,
169: 	},
170: ]);
171: const completedSetupSteps = $derived(
172: 	setupChecklist.filter((item) => item.complete).length,
173: );
174: 
175: function formatPrice(value: number) {
176: 	return new Intl.NumberFormat("en-IE", {
177: 		style: "currency",
178: 		currency: "EUR",
179: 		minimumFractionDigits: value % 1 === 0 ? 0 : 2,
180: 	}).format(value);
181: }
182: 
183: // The date picker and time inputs read the instants on the Dublin clock.
184: const workshopDateValue = $derived(
185: 	start ? civilCalendarDate(start.date) : undefined,
186: );
187: const startTime = $derived(start?.time ?? "");
188: const endTime = $derived(end?.time ?? "");
189: 
190: // A new time keeps its field's Dublin date: the start's own, else Dublin
191: // today; the end's own, else the start's, else Dublin today.
192: function updateWorkshopTime(time: string, field: "start" | "end") {
193: 	if (field === "start") {
194: 		const instant = dublinInstant(start?.date ?? dublinToday(), time);
195: 		if (instant) remoteForm.fields.workshop_date.set(instant);
196: 		return;
197: 	}
198: 
199: 	const instant = dublinInstant(
200: 		end?.date ?? start?.date ?? dublinToday(),
201: 		time,
202: 	);
203: 	if (instant) remoteForm.fields.workshop_end_date.set(instant);
204: }
205: 
206: // A new date keeps each field's Dublin time, or the Dublin defaults.
207: function updateWorkshopDate(date: CalendarDate | undefined) {
208: 	const civilDate = civilIsoDate(date);
209: 	if (!civilDate) return;
210: 	const startInstant = dublinInstant(
211: 		civilDate,
212: 		start?.time ?? DEFAULT_START_TIME,
213: 	);
214: 	const endInstant = dublinInstant(civilDate, end?.time ?? DEFAULT_END_TIME);
215: 	if (startInstant) remoteForm.fields.workshop_date.set(startInstant);
216: 	if (endInstant) remoteForm.fields.workshop_end_date.set(endInstant);
217: }
218: 
219: // Edit permissions
220: const isWorkshopEditable = $derived.by(() => {
221: 	if (mode === "create") return true;
222: 	if (workshopStatus === "published") return false;
223: 	if (workshopEditable !== undefined) return workshopEditable;
224: 	return workshopStatus === "planned";
225: });
226: 
227: const canEditPricing = $derived.by(() => {
228: 	if (mode === "create") return true;
229: 	if (workshopStatus === "planned") return true;
230: 	return !priceEditingDisabled;
231: });
232: 
