15: import {
16: 	type CommandIssue as Issue,
17: 	type CommandResponse,
18: 	type CommandResult,
19: 	commandResult,
20: 	type FieldAttribution,
21: } from "#lib/server/api/command-result.js";
22: 
23: export type InventoryCommandResponse<Data> = CommandResponse<Data>;
24: export type InventoryCommandResult<Data> = CommandResult<Data>;
25: 
26: type IssueBuilder = (message: string) => Issue;
27: 
28: export interface InventoryCommandTranslation<Field extends string> {
29: 	/** Form-level message when Phoenix sends no `detail`. */
30: 	fallback: string;
31: 	/** Form fields whose API names Phoenix may attribute a rejection to. */
32: 	fields: readonly Field[];
33: 	/** The remote form's `issue` builder (or a fake with the same fields). */
34: 	issue: Record<Field, IssueBuilder>;
35: 	/**
36: 	 * Property Definition labels by id, read only when Phoenix rejects a
37: 	 * property value (`values.<definitionId>`). A failed lookup degrades to
38: 	 * "a property".
39: 	 */
40: 	propertyLabels?: () => Promise<ReadonlyMap<string, string>>;
41: }
42: 
43: const VALUE_FIELD_PREFIX = "values.";
44: 
45: export async function inventoryCommand<Data, const Field extends string>(
46: 	request: Promise<InventoryCommandResponse<Data>>,
47: 	translation: InventoryCommandTranslation<Field>,
48: ): Promise<InventoryCommandResult<Data>> {
49: 	return commandResult(request, translation.fallback, (fields) =>
50: 		attributeFields(translation, fields),
51: 	);
52: }
53: 
54: async function attributeFields<Field extends string>(
55: 	translation: InventoryCommandTranslation<Field>,
56: 	fields: ApiFieldMessages[],
57: ): Promise<FieldAttribution> {
58: 	const issues: Issue[] = [];
59: 	let unattributed = false;
60: 	const labels = fields.some(({ field }) =>
61: 		field.startsWith(VALUE_FIELD_PREFIX),
62: 	)
63: 		? await loadLabels(translation.propertyLabels)
64: 		: new Map<string, string>();
65: 
66: 	for (const { field, messages } of fields) {
67: 		if (field.startsWith(VALUE_FIELD_PREFIX)) {
68: 			const build = issueFor(translation, "values");
69: 			if (!build) {
70: 				unattributed = true;
71: 				continue;
72: 			}
73: 			const label = labels.get(field.slice(VALUE_FIELD_PREFIX.length));
74: 			issues.push(
75: 				...messages.map((reason) => build(propertyValueMessage(label, reason))),
76: 			);
77: 			continue;
78: 		}
79: 		const build = issueFor(translation, field);
80: 		if (!build) {
81: 			unattributed = true;
82: 			continue;
83: 		}
84: 		issues.push(...messages.map((message) => build(message)));
85: 	}
86: 
87: 	// Keep what no field can show visible at form level.
88: 	return { issues, unattributed };
89: }
90: 
91: function issueFor<Field extends string>(
92: 	translation: InventoryCommandTranslation<Field>,
93: 	field: string,
94: ): IssueBuilder | undefined {
95: 	const known = translation.fields.find((candidate) => candidate === field);
96: 	return known === undefined ? undefined : translation.issue[known];
97: }
98: 
99: async function loadLabels(
100: 	load: (() => Promise<ReadonlyMap<string, string>>) | undefined,
101: ): Promise<ReadonlyMap<string, string>> {
102: 	try {
103: 		return (await load?.()) ?? new Map();
104: 	} catch (cause) {
105: 		// Labels only name the property; the rejection still reaches the form.
106: 		Sentry.captureException(cause);
107: 		return new Map();
108: 	}
109: }
110: 
111: /** One sentence per `DhcWeb.InventoryHTTP.value_fields/1` reason. */
112: function propertyValueMessage(label: string | undefined, reason: string) {
113: 	const name = label ?? "a property";
114: 	const sentence = (() => {
115: 		switch (reason) {
116: 			case "required":
117: 				return `${name} is required`;
118: 			case "type_mismatch":
119: 				return `Enter a valid value for ${name}`;
120: 			case "unknown_option":
121: 				return `Choose one of the options for ${name}`;
122: 			case "retired_option":
123: 				return `The option chosen for ${name} has been retired`;
124: 			case "retired_definition":
125: 				return `${name} has been retired and can no longer be set`;
126: 			case "unknown_definition":
127: 				return `${name} does not belong to this category`;
128: 			default:
129: 				return `${name}: ${reason}`;
130: 		}
131: 	})();
132: 	return sentence.charAt(0).toUpperCase() + sentence.slice(1);
133: }

