export interface DestinationFacts {
  destinationName?: string | null;
  destinationAddress?: string | null;
  directionsUrl?: string | null;
}

/** The destination detail lines an attendee surface shows, most useful first. */
export function destinationLines(workshop: DestinationFacts): string[]

/** The directions link for an attendee: the validated manual Maps link, else a Maps search built from the destination facts. */
export function directionsHref(workshop: DestinationFacts): string | undefined
```

Constructed search URL: `https://www.google.com/maps/search/?api=1&query=` + encodeURIComponent([name, address].join(", ")). Only when there are destination facts. Safe external link: `target="_blank" rel="noopener noreferrer"` in markup.

