import { commandResult, type CommandIssue, type FieldAttribution } from "#lib/server/api/command-result.js";
import { type ApiFieldMessages, apiProblem? no
```

The API→form field map:
```ts
const destinationIssueFields = {
	destinationName: "destination_name",
	destinationAddress: "destination_address",
	directionsUrl: "directions_url",
} as const;

type DestinationIssue = (message: string) => CommandIssue;

function attributeDestinationRejection(
	issue: { destination_name: DestinationIssue; destination_address: DestinationIssue; directions_url: DestinationIssue },
) {
	return (fields: ApiFieldMessages[]): FieldAttribution => {
		const issues: CommandIssue[] = [];
		let unattributed = false;
		for (const { field, messages } of fields) {
			const formField = destinationIssueFields[field as keyof typeof destinationIssueFields];
			if (!formField) { unattributed = true; continue; }
			issues.push(...messages.map((message) => issue[formField](message)));
		}
		return { issues, unattributed };
	};
}
```

Hmm wait — typing `issue` param generically. The handler's `issue` for CreateWorkshopRemoteSchema has all keys; I'll just take the structural subset.

