{
  "items": [
    {
      "path": "tools.linear.list_issue_labels",
      "description": "List available issue labels in a Linear workspace or team. A retired label carries `retiredAt` and cannot be applied to new issues.",
      "signature": "tools.linear.list_issue_labels({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /** Filter by name */
  name?: string,
  /** Team name or ID */
  team?: string,
  /** Include archived items. @default false */
  includeArchived?: boolean,
  /**
   * Include label groups in the results, marked with `isGroup`. A group cannot be applied directly; retiring or restoring one cascades to its child labels
   * @default false
