{
  "items": [
    {
      "path": "tools.linear.save_issue",
      "description": "Create or update a Linear issue. If `id` is provided, updates the existing issue; otherwise creates a new one. When creating, `team` is required, and `title` is required unless `template` is set. Note: use `assignee` (not `assigneeId`) to set the assignee — it accepts a user ID, name, email, or "me".",
      "signature": "tools.linear.save_issue({
  /**
   * Only for updating an existing issue. Pass the issue ID or identifier (e.g., LIN-123). Do NOT pass this parameter when creating a new issue.
   */
  id?: string,
  /** Issue title (required when creating, unless template is set) */
  title?: string,
  /**
   * Content as Markdown. Do not escape the string — use literal newlines and special characters, not escape sequences. To mention a user, use @displayName (e.g., @johndoe)
   */
  description?: string,
  /**
   * Partial edits applied to the current content, in order and atomically (one failing operation aborts the whole save). Every anchor string must match the current content exactly once. Only valid on update, in place of the full content/description field
   * @minItems 1 @maxItems 50
   */
  patch?: Array<{
        op: "replace",
        /** Exact text to replace. Must match the current content exactly once. @minLength 1 */
        old_string: string,
        /** Replacement text. Empty string deletes the match */
        new_string: string,
        /** Replace every occurrence instead of requiring a unique match */
        replace_all?: boolean,
      } | {
        op: "insert_before",
        /** Exact text to insert before. Must match the current content exactly once. @minLength 1 */
        anchor: string,
        /** Text to insert directly before the anchor. Include separators (e.g. "\n\n"). @minLength 1 */
        text: string,
      } | {
        op: "insert_after",
        /** Exact text to insert after. Must match the current content exactly once. @minLength 1 */
        anchor: string,
        /** Text to insert directly after the anchor. Include separators (e.g. "\n\n"). @minLength 1 */
        text: string,
      } | {
        op: "prepend",
        /** Text to insert at the very start of the content. @minLength 1 */
        text: string,
      } | {
        op: "append",
        /** Text to insert at the very end of the content. @minLength 1 */
        text: string,
